/** Sets (or clears, with null) GA's user_id. Pass an opaque id, never an email. */
export function setGoogleUserId(
  userId: string | null,
  win: GoogleTagWindow = globalThis as unknown as GoogleTagWindow,
): void {
  const state = loaded.get(win)
  if (!state || (userId !== null && EMAIL_PATTERN.test(userId))) {
    return
  }
  state.gtag('set', { user_id: userId })
}

/**
 * Extracts GA's client id from the `_ga` cookie (`GA1.1.<random>.<timestamp>`
 * → `<random>.<timestamp>`), the value the Measurement Protocol keys on.
 */
export function readGaClientId(cookies: string): string | null {
  for (const part of cookies.split(';')) {
    const trimmed = part.trim()
    if (!trimmed.startsWith('_ga=')) {
      continue
    }
    const match = GA_COOKIE_PATTERN.exec(trimmed.slice('_ga='.length))
    return match ? match[1] : null
  }
  return null
}
